let builderProjectEpoch = 0;

function requestProjectAnimationFrame(
    callback
  ) {
    const projectEpoch =
      builderProjectEpoch;
    const frameAuditRecord =
      window.__RML_FRAME_AUDIT_RECORD__;
    const frameAuditScheduledAt =
      typeof frameAuditRecord === "function"
        ? performance.now()
        : 0;
    const frameAuditDeepTrace = Boolean(
      window.__RML_FRAME_AUDIT_DEEP_TRACE__ ===
        true
    );
    const frameAuditScheduleStack =
      typeof frameAuditRecord === "function" &&
      frameAuditDeepTrace
        ? new Error(
            "requestProjectAnimationFrame scheduled here"
          ).stack || ""
        : "";
    return window.requestAnimationFrame(
      timestamp => {
        if (
          projectEpoch !==
            builderProjectEpoch
        ) {
          return;
        }
        const frameAuditStartedAt =
          typeof frameAuditRecord === "function"
            ? performance.now()
            : 0;
        try {
          callback(timestamp);
        } finally {
          if (
            typeof frameAuditRecord === "function"
          ) {
            const duration =
              performance.now() -
              frameAuditStartedAt;
            if (duration >= 4) {
              try {
                frameAuditRecord({
                  type:
                    "project-animation-frame",
                  build:
                    window.RMLBuilderBuildId || "",
                  duration,
                  queueDelay:
                    frameAuditStartedAt -
                    frameAuditScheduledAt,
                  frameTimestamp: timestamp,
                  projectEpoch,
                  activeScope:
                    customCSharpEditor
                      ? "custom-csharp-file"
                      : apiCompositeEditor
                        ? "api-composite"
                        : "runtime-root",
                  nodeCount:
                    graph?.nodes?.length || 0,
                  connectionCount:
                    graph?.connections?.length || 0,
                  phase:
                    dom.root?.dataset
                      ?.rmlGraphPhase || "",
                  visibility:
                    document.visibilityState,
                  callbackName:
                    callback.name || "",
                  callbackSource:
                    frameAuditDeepTrace
                      ? Function.prototype.toString
                          .call(callback)
                          .slice(0, 1024)
                      : "",
                  scheduleStack:
                    frameAuditScheduleStack
                });
              } catch {
              }
            }
          }
        }
      }
    );
  }

function waitForGraphPaintOpportunity() {
    const projectEpoch =
      builderProjectEpoch;
    return new Promise(resolve => {
      const finish = () => {
        window.setTimeout(
          () => resolve(
            projectEpoch ===
              builderProjectEpoch
          ),
          0
        );
      };
      if (
        document.visibilityState ===
          "hidden"
      ) {
        finish();
        return;
      }
      window.requestAnimationFrame(() => {
        if (
          projectEpoch !==
            builderProjectEpoch
        ) {
          resolve(false);
          return;
        }
        window.requestAnimationFrame(() => {
          if (
            projectEpoch !==
              builderProjectEpoch
          ) {
            resolve(false);
            return;
          }
          finish();
        });
      });
    });
  }

