    graphScrollLayerIndicatorTimer = 0;

    if (!graphScrollLayerIndicator) {
      return;
    }

    graphScrollLayerIndicator
      .classList.remove("visible");

    if (immediate) {
      graphScrollLayerIndicator.hidden =
        true;
      return;
    }

    graphScrollLayerIndicatorTimer =
      window.setTimeout(() => {
        if (graphScrollLayerIndicator) {
          graphScrollLayerIndicator.hidden =
            true;
        }
      }, 180);
