        element.getBoundingClientRect();
      const unchanged =
        Number.isFinite(lastLeft) &&
        Math.abs(rectangle.left - lastLeft) < 0.1 &&
        Math.abs(rectangle.top - lastTop) < 0.1;

      stableFrames = unchanged
        ? stableFrames + 1
        : 0;
      lastLeft = rectangle.left;
      lastTop = rectangle.top;

